import { defineComponent, h, type PropType } from 'vue';
import { getPaginationSizeKey, paginationStyleKeys } from '../lib/core';
import type { PaginationSize } from '../lib/core';
import styles from './pagination.module.scss';

function renderChevronLeft() {
	return h(
		'svg',
		{
			xmlns: 'http://www.w3.org/2000/svg',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
		},
		[h('path', { d: 'm15 18-6-6 6-6' })],
	);
}

function renderChevronRight() {
	return h(
		'svg',
		{
			xmlns: 'http://www.w3.org/2000/svg',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
		},
		[h('path', { d: 'm9 18 6-6-6-6' })],
	);
}

function renderMoreHorizontal() {
	return h(
		'svg',
		{
			class: styles[paginationStyleKeys.ellipsisIcon],
			xmlns: 'http://www.w3.org/2000/svg',
			viewBox: '0 0 24 24',
			fill: 'currentColor',
		},
		[h('circle', { cx: '12', cy: '12', r: '1' }), h('circle', { cx: '19', cy: '12', r: '1' }), h('circle', { cx: '5', cy: '12', r: '1' })],
	);
}

export const Pagination = defineComponent({
	name: 'Pagination',
	setup(_props, { slots, attrs }) {
		return () => h('nav', { ...attrs, role: 'navigation', 'aria-label': 'pagination', class: [styles[paginationStyleKeys.root], attrs.class] }, slots.default?.());
	},
});

export const PaginationContent = defineComponent({
	name: 'PaginationContent',
	setup(_props, { slots, attrs }) {
		return () => h('ul', { ...attrs, class: [styles[paginationStyleKeys.content], attrs.class] }, slots.default?.());
	},
});

export const PaginationItem = defineComponent({
	name: 'PaginationItem',
	setup(_props, { slots, attrs }) {
		return () => h('li', { ...attrs, class: [styles[paginationStyleKeys.item], attrs.class] }, slots.default?.());
	},
});

export const PaginationLink = defineComponent({
	name: 'PaginationLink',
	props: {
		href: String,
		isActive: { type: Boolean, default: false },
		size: {
			type: String as PropType<PaginationSize>,
			default: 'icon',
		},
	},
	setup(props, { slots, attrs }) {
		return () =>
			h(
				'a',
				{
					...attrs,
					href: props.href,
					'aria-current': props.isActive ? 'page' : undefined,
					'data-active': props.isActive,
					class: [styles[paginationStyleKeys.link], styles[getPaginationSizeKey(props.size)], props.isActive ? styles.isActive : '', attrs.class],
				},
				slots.default?.(),
			);
	},
});

export const PaginationPrevious = defineComponent({
	name: 'PaginationPrevious',
	setup(_props, { slots, attrs }) {
		return () =>
			h(
				'a',
				{
					...attrs,
					'aria-label': 'Go to previous page',
					class: [styles[paginationStyleKeys.link], styles.sizeDefault, styles.gapSm, attrs.class],
				},
				[renderChevronLeft(), h('span', { class: styles.paginationHideSm }, slots.default?.() ?? 'Previous')],
			);
	},
});

export const PaginationNext = defineComponent({
	name: 'PaginationNext',
	setup(_props, { slots, attrs }) {
		return () =>
			h(
				'a',
				{
					...attrs,
					'aria-label': 'Go to next page',
					class: [styles[paginationStyleKeys.link], styles.sizeDefault, styles.gapSm, attrs.class],
				},
				[h('span', { class: styles.paginationHideSm }, slots.default?.() ?? 'Next'), renderChevronRight()],
			);
	},
});

export const PaginationEllipsis = defineComponent({
	name: 'PaginationEllipsis',
	setup(_props, { slots, attrs }) {
		return () =>
			h('span', { ...attrs, 'aria-hidden': 'true', class: [styles[paginationStyleKeys.ellipsis], attrs.class] }, [
				renderMoreHorizontal(),
				h('span', { class: styles[paginationStyleKeys.srOnly] }, slots.default?.() ?? 'More pages'),
			]);
	},
});

export default Pagination;

@use '../../../styles/variables/colors' as *;

.root {
	margin-left: auto;
	margin-right: auto;
	display: flex;
	width: 100%;
	justify-content: center;
}

.content {
	display: flex;
	flex-direction: row;
	align-items: center;
	gap: var(--tile-pagination-gap, $spacing-1);
}

.item {
	display: list-item;
}

.link {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: $spacing-2;
	height: var(--tile-pagination-height, 2.25rem);
	min-width: var(--tile-pagination-height, 2.25rem);
	padding: var(--tile-pagination-padding, 0 $spacing-3);
	border-radius: var(--tile-pagination-radius, $radius);
	font-size: var(--tile-pagination-font-size, $text-sm);
	font-weight: var(--tile-pagination-font-weight, $font-medium);
	white-space: nowrap;
	color: var(--tile-pagination-foreground, $foreground);
	transition: all $transition-fast;
	outline: none;

	svg {
		width: 1rem;
		height: 1rem;
	}

	&.sizeSm {
		height: var(--tile-pagination-sm-height, 2rem);
		min-width: var(--tile-pagination-sm-height, 2rem);
		padding: var(--tile-pagination-sm-padding, 0 $spacing-2);
		border-radius: var(--tile-pagination-sm-radius, $radius-sm);
		font-size: var(--tile-pagination-sm-font-size, $text-xs);
	}

	&.sizeLg {
		height: var(--tile-pagination-lg-height, 2.5rem);
		min-width: var(--tile-pagination-lg-height, 2.5rem);
		padding: var(--tile-pagination-lg-padding, 0 $spacing-5);
	}

	&.sizeIcon {
		width: var(--tile-pagination-height, 2.25rem);
		padding: 0;
	}

	&.isActive {
		border: 1px solid var(--tile-pagination-active-border, $border);
		background-color: var(--tile-pagination-active-background, $background);
		box-shadow: var(--tile-pagination-active-shadow, $shadow-sm);
	}

	&:hover {
		background-color: var(--tile-pagination-hover-background, $accent);
		color: var(--tile-pagination-hover-foreground, $accent-foreground);
		text-decoration: none;
	}

	&:focus-visible {
		box-shadow: var(--tile-pagination-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}
}

.ellipsis {
	display: flex;
	width: 2.25rem;
	height: 2.25rem;
	align-items: center;
	justify-content: center;
}

.ellipsisIcon {
	width: 1rem;
	height: 1rem;
}

.srOnly {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
}

.gapSm {
	gap: $spacing-1;
	padding-inline: $spacing-2_5;
}

.paginationHideSm {
	display: none;

	@media (min-width: 640px) {
		display: block;
	}
}
